15	export type NavChild = { label: string; href: string; badge?: number };
16	export type NavItem = {
17	  label: string;
18	  href: string;
19	  /**
20	   * Leading icon (key into the `icons` map below). Both portals supply one for
21	   * every item; the link degrades to its initial if a key is ever missing.
22	   */
23	  icon?: string;
24	  badge?: number;
25	  /**
26	   * Secondary destinations that live *behind* this entry. The sidebar never
27	   * expands them — the admin portal surfaces them as in-page sub-tabs (see
28	   * components/admin/SubTabs.tsx). They exist here so the sidebar row stays
29	   * highlighted while you're on one of them, and so ⌘K can still jump straight
30	   * to any of them. Customer nav passes none and renders exactly as before.
31	   */
32	  children?: NavChild[];
33	};
34	export type NavSection = {
35	  label?: string;
36	  items: NavItem[];
37	};
