178	function Logo({ tag, collapsed }: { tag?: string; collapsed?: boolean }) {
179	  return (
180	    <Link href="/" className={`flex items-center gap-2.5 px-2 ${collapsed ? "lg:justify-center lg:px-0" : ""}`}>
181	      {/* eslint-disable-next-line @next/next/no-img-element */}
182	      <img
183	        src="/logo.png"
184	        alt="Nxeon"
185	        style={{ height: 40, width: "auto" }}
186	        className={`select-none object-contain ${collapsed ? "lg:hidden" : ""}`}
187	      />
188	      {/* Compact mark, shown only when the desktop rail is collapsed. */}
189	      {/* eslint-disable-next-line @next/next/no-img-element */}
190	      <img
191	        src="/favicon.svg"
192	        alt="Nxeon"
193	        style={{ height: 30, width: 30 }}
194	        className={`hidden select-none object-contain ${collapsed ? "lg:block" : ""}`}
195	      />
196	      {tag && (
197	        <span
198	          className={`rounded-md border border-amber-400/30 bg-amber-400/10 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-widest text-amber-300 ${
199	            collapsed ? "lg:hidden" : ""
