208	
209	export function Shell({
210	  nav,
211	  user,
212	  notifications,
213	  impersonation,
214	  tag,
215	  children,
216	}: {
217	  nav: NavSection[];
218	  user: { name: string; email: string; role: string; balanceCents: number };
219	  notifications: ShellNotification[];
220	  impersonation?: { adminName: string; targetEmail: string } | null;
221	  tag?: string;
222	  children: React.ReactNode;
223	}) {
224	  const pathname = usePathname();
225	  // Full-bleed routes (the mail + calendar apps) opt out of the centered/padded
226	  // main so they fill the entire content area under the header with no gap.
227	  const fullBleed =
228	    pathname === "/dashboard/mail" || pathname === "/dashboard/calendar" || pathname === "/admin/inbox" || pathname === "/admin/board";
229	  const [notifOpen, setNotifOpen] = useState(false);
230	  const [sidebarOpen, setSidebarOpen] = useState(false);
231	  // Desktop-only main-sidebar collapse. Persisted so it holds across every
232	  // portal page (mail, calendar, servers…). On mobile the drawer always renders
233	  // expanded — every collapse style below is gated to the `lg:` breakpoint.
234	  const [collapsed, setCollapsed] = useState(false);
235	  const [, startTransition] = useTransition();
236	
237	  useEffect(() => {
238	    try {
239	      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
240	    } catch {}
241	  }, []);
242	  function toggleCollapsed() {
243	    setCollapsed((c) => {
244	      const next = !c;
245	      try {
246	        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
247	      } catch {}
248	      return next;
249	    });
250	  }
251	
252	  /**
253	   * Publish the rail's current width so `position: fixed` chrome outside this
254	   * subtree can sit beside it instead of guessing.
255	   *
256	   * The terminal dock hardcoded `lg:left-60` (15rem) while the rail collapses to
257	   * `lg:w-[4.75rem]`, leaving a ~10rem dead gutter down the left of the terminal
258	   * whenever a customer collapsed the sidebar. A CSS variable on the document
259	   * element reaches the dock regardless of where it is mounted.
260	   */
261	  useEffect(() => {
262	    document.documentElement.style.setProperty("--nx-rail-w", collapsed ? "4.75rem" : "15rem");
263	  }, [collapsed]);
264	
265	  /**
266	   * Is the mobile drawer currently a drawer at all? Below `lg` the rail is an
267	   * off-canvas panel translated out of view; at `lg` and up it is the ordinary
268	   * page sidebar and must never be hidden or inerted.
269	   *
270	   * Starts `true` (desktop) so the server render and the first client render
271	   * agree, and so a JS-less or pre-hydration page never has its navigation
272	   * inerted. The listener corrects it a tick later.
273	   */
274	  const [isDesktopRail, setIsDesktopRail] = useState(true);
275	  useEffect(() => {
276	    const mq = window.matchMedia("(min-width: 1024px)");
277	    const sync = () => setIsDesktopRail(mq.matches);
278	    sync();
279	    mq.addEventListener("change", sync);
280	    return () => mq.removeEventListener("change", sync);
281	  }, []);
282	  /**
283	   * Closed, off-canvas and out of reach. The rehearsal found the closed drawer
284	   * still `visibility: visible` with no `aria-hidden` and **25 focusable
285	   * descendants in the tab order** — so a keyboard user on a phone tabbed
286	   * through the entire hidden navigation before reaching the page.
287	   */
288	  const drawerHidden = !isDesktopRail && !sidebarOpen;
289	
290	  // Escape closes the drawer. It did nothing at all before: the drawer had no
291	  // close button either (the only in-drawer button is the collapse toggle, which
292	  // is `lg:flex`), so a backdrop tap was the single way out.
293	  useEffect(() => {
294	    if (!sidebarOpen) return;
295	    const onKey = (e: KeyboardEvent) => {
296	      if (e.key === "Escape") setSidebarOpen(false);
297	    };
298	    window.addEventListener("keydown", onKey);
299	    return () => window.removeEventListener("keydown", onKey);
300	  }, [sidebarOpen]);
301	
302	  // Navigating from a drawer link must close the drawer — otherwise the new page
303	  // renders behind a panel the customer has to dismiss by hand.
304	  useEffect(() => {
305	    setSidebarOpen(false);
306	  }, [pathname]);
307	
308	  // Opening the bell marks everything read server-side, but `notifications` is a
309	  // prop rendered from the initial server load, so without this the blue count
310	  // and the bold titles would stay lit for the rest of the session even though
311	  // the server now considers them read — a "you have unread mail" badge that
312	  // won't clear. Track the open-and-marked edge locally and reconcile the view
313	  // to it. Once marked, unread is 0 and nothing renders as unread.
314	  const [notifMarked, setNotifMarked] = useState(false);
315	  // The optimistic clear only covers the window between opening the bell and the
316	  // server revalidating. Once a fresh `notifications` prop arrives (e.g. a new
317	  // notification, or the read state confirmed), drop the optimism so a genuinely
318	  // new unread item still lights the badge.
319	  useEffect(() => {
320	    setNotifMarked(false);
321	  }, [notifications]);
322	  const unread = notifMarked ? 0 : notifications.filter((n) => !n.readAt).length;
323	
324	  // Live unread-INBOX count for the "Inbox" nav badge. Polled client-side because
325	  // IMAP is far too slow to run on every server-side layout render. Only polls when
326	  // the portal actually has a Mail entry; fails soft to no badge.
327	  const hasMailNav = nav.some((s) => s.items.some((i) => i.href === "/dashboard/mail"));
328	  const [mailUnread, setMailUnread] = useState(0);
329	  useEffect(() => {
330	    if (!hasMailNav) return;
331	    let alive = true;
332	    const load = () =>
333	      fetch("/api/mail/unread")
334	        .then((r) => (r.ok ? r.json() : { unread: 0 }))
335	        .then((d) => alive && setMailUnread(Number(d?.unread) || 0))
336	        .catch(() => {});
337	    load();
338	    const id = setInterval(load, 60_000);
339	    return () => {
340	      alive = false;
341	      clearInterval(id);
342	    };
343	  }, [hasMailNav]);
344	
345	  // Live Matrix status for the "Matrix" nav tag. Polls the user's own console
346	  // builds: shows "running" while a build is in flight, and "update" when one
347	  // has reached a state worth a look (finished, or a plan awaiting approval)
348	  // that the customer hasn't seen since they last opened the workspace. Only
349	  // polls when the portal has a Matrix entry; fails soft to no tag.
350	  const hasMatrixNav = nav.some((s) => s.items.some((i) => i.href === "/dashboard/build"));
351	  const [matrixStatus, setMatrixStatus] = useState<{
352	    running: number;
353	    needsAttention: number;
354	    lastEventAt: string | null;
355	  }>({ running: 0, needsAttention: 0, lastEventAt: null });
356	  // Timestamp (ms) the customer last "saw" Matrix. Seeded to now on first ever
357	  // load so pre-existing finished builds don't light a stale "update" tag —
358	  // only events from here forward count. Bumped whenever they open the workspace.
359	  const [matrixSeenAt, setMatrixSeenAt] = useState<number>(0);
360	  useEffect(() => {
361	    try {
362	      const v = localStorage.getItem("nxeon.matrix.seenAt");
363	      if (v) {
364	        setMatrixSeenAt(Number(v) || 0);
365	      } else {
366	        const now = Date.now();
367	        setMatrixSeenAt(now);
368	        localStorage.setItem("nxeon.matrix.seenAt", String(now));
369	      }
370	    } catch {
371	      setMatrixSeenAt(Date.now());
372	    }
373	  }, []);
374	  useEffect(() => {
375	    if (!hasMatrixNav) return;
376	    let alive = true;
377	    const load = () =>
378	      fetch("/api/claude/console-status")
379	        .then((r) => (r.ok ? r.json() : null))
380	        .then((d) => {
381	          if (alive && d) {
382	            setMatrixStatus({
383	              running: Number(d.running) || 0,
384	              needsAttention: Number(d.needsAttention) || 0,
385	              lastEventAt: d.lastEventAt ?? null,
386	            });
387	          }
388	        })
389	        .catch(() => {});
390	    load();
391	    const id = setInterval(load, 20_000);
392	    return () => {
393	      alive = false;
394	      clearInterval(id);
395	    };
396	  }, [hasMatrixNav]);
397	  // Opening the workspace marks everything seen (clears the "update" tag). Also
398	  // re-marks if a fresh event lands while they're already on the page.
399	  useEffect(() => {
400	    if (pathname !== "/dashboard/build") return;
401	    const now = Date.now();
402	    setMatrixSeenAt(now);
403	    try {
404	      localStorage.setItem("nxeon.matrix.seenAt", String(now));
405	    } catch {}
406	  }, [pathname, matrixStatus.lastEventAt]);
407	  const matrixTag: "running" | "update" | null =
408	    matrixStatus.running > 0
409	      ? "running"
410	      : matrixStatus.lastEventAt != null && Date.parse(matrixStatus.lastEventAt) > matrixSeenAt
411	        ? "update"
412	        : null;
413	
414	  // Escape closes the notifications dropdown too (it only closed the drawer
415	  // before), matching the palette and drawer. A click anywhere else dismisses it
416	  // via the click-away layer rendered below.
417	  useEffect(() => {
418	    if (!notifOpen) return;
419	    const onKey = (e: KeyboardEvent) => {
420	      if (e.key === "Escape") setNotifOpen(false);
421	    };
422	    window.addEventListener("keydown", onKey);
423	    return () => window.removeEventListener("keydown", onKey);
424	  }, [notifOpen]);
425	
426	  // Flatten for the command palette: every sidebar entry plus every secondary
427	  // destination hidden behind it, so ⌘K still reaches all ~41 admin routes even
428	  // though only 14 of them have a sidebar row. The child sharing the entry's own
429	  // href is skipped so the landing page isn't listed twice. Flat items (customer
430	  // portal) pass through unchanged.
431	  const flatNav = nav.flatMap((s) =>
432	    s.items.flatMap((i) => [
433	      { label: i.label, href: i.href, section: s.label },
434	      ...(i.children ?? [])
435	        .filter((c) => c.href !== i.href)
436	        .map((c) => ({ label: c.label, href: c.href, section: s.label })),
437	    ])
438	  );
439	
440	  return (
441	    // The terminal dock lives at the shell level so a shell session survives
442	    // in-portal navigation: App Router keeps Shell mounted across page changes,
443	    // so the dock (and its live sockets) is never unmounted. The provider is
444	    // inert until a page calls useTerminalDock().openSession(...).
445	    <TerminalDockProvider>
446	    {/* The compose provider lives at the shell level for the same reason as the
447	        terminal dock: App Router keeps Shell mounted across in-portal navigation,
448	        so an open (or minimized) mail composer — and its in-progress draft —
449	        survives moving between dashboard pages. It renders the composer through a
450	        portal to <body> and is inert until a mail page calls useCompose().open(). */}
451	    <ComposeProvider>
452	    {/* The Matrix workspace lives at the shell level for the same reason as the
453	        terminal dock and compose provider: App Router keeps Shell mounted across
454	        in-portal navigation, so open build consoles and their live server
455	        terminals survive moving between pages. It is lazy (nothing until the
456	        customer first opens Matrix) and inert on every non-customer route. */}
457	    <MatrixProvider>
458	    <div className="flex min-h-screen">
459	      <CommandPalette nav={flatNav} />
460	      <FeedbackWidget />
461	      <VisitTracker kind="portal" />
462	
463	      {/* Sidebar */}
464	      <aside
465	        id="portal-sidebar"
466	        // `lg:sticky lg:top-0 lg:h-screen`, NOT `lg:static`: static put the rail in
467	        // normal document flow, so on desktop it scrolled away with the page and
468	        // navigation disappeared on any long view. Sticky keeps it in flow (main
469	        // content still sits beside it, no overlap) while pinning it to the
470	        // viewport. The <nav> inside already has flex-1 + overflow-y-auto, so a
471	        // long menu scrolls within the rail rather than pushing it off-screen.
472	        className={`fixed inset-y-0 left-0 z-40 flex w-60 flex-col border-r border-white/[0.06] bg-navy-900/80 backdrop-blur-xl transition-all lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${
473	          collapsed ? "lg:w-[4.75rem]" : "lg:w-60"
474	        } ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}
475	        // Off-canvas and closed on a phone: out of the tab order and out of the
